// Wellfound embeds job data in __NEXT_DATA__ JSON in the HTML
const html = $input.first().json.data || $input.first().json || '';
const htmlStr = typeof html === 'string' ? html : JSON.stringify(html);
const match = htmlStr.match(/<script id="__NEXT_DATA__" type="application\/json">([\s\S]*?)<\/script>/);
if (!match) return [{ json: { _parse_note: 'Wellfound: no __NEXT_DATA__ found - site may require auth or JS rendering' } }];
try {
  const nextData = JSON.parse(match[1]);
  // Try to find jobs in the nested structure
  const jobs = nextData?.props?.pageProps?.jobs ||
                nextData?.props?.pageProps?.searchResults?.jobs ||
                [];
  if (!jobs.length) return [{ json: { _parse_note: 'Wellfound: no jobs extracted from page data' } }];
  return jobs.map(job => ({
    json: {
      source: 'Wellfound',
      job_title: (job.title || job.jobType || '').trim(),
      company: (job.startup?.name || job.company?.name || '').trim(),
      job_url: job.slug ? `https://wellfound.com/jobs/${job.slug}` : (job.url || ''),
      location_text: job.locationNames?.join(', ') || job.remoteConfig || 'Remote',
      salary: job.compensation || '',
      description: (job.description || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim(),
      posted_date: job.createdAt ? job.createdAt.split('T')[0] : new Date().toISOString().split('T')[0],
      tags: Array.isArray(job.tags) ? job.tags.join(', ') : ''
    }
  }));
} catch(e) {
  return [{ json: { _parse_note: 'Wellfound parse error: ' + e.message } }];
}

const data = $input.first().json;
const companies = data.companies || data || [];
const jobs = [];
if (Array.isArray(companies)) {
  for (const co of companies) {
    const coJobs = co.jobs || [];
    for (const job of coJobs) {
      jobs.push({
        json: {
          source: 'YC Work at Startup',
          job_title: (job.title || '').trim(),
          company: (co.name || '').trim(),
          job_url: job.url ? job.url : (co.slug ? `https://www.workatastartup.com/companies/${co.slug}` : ''),
          location_text: job.location_or_remote || (job.remote ? 'Remote Worldwide' : ''),
          salary: job.salary_range || '',
          description: (job.description || co.description || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim(),
          posted_date: job.created_at ? job.created_at.split('T')[0] : new Date().toISOString().split('T')[0],
          tags: Array.isArray(job.skills) ? job.skills.join(', ') : ''
        }
      });
    }
  }
}
return jobs.length ? jobs : [{ json: { _parse_note: 'YC: no jobs found in response' } }];

const data = $input.first().json;
// Otta returns JSON or HTML depending on the endpoint
const jobs = data.jobs || data.results || data.data || [];
if (!Array.isArray(jobs) || !jobs.length) {
  return [{ json: { _parse_note: 'Otta: endpoint may require API key or different URL - check otta.com API docs' } }];
}
return jobs.map(job => ({
  json: {
    source: 'Otta',
    job_title: (job.title || job.name || '').trim(),
    company: (job.company?.name || job.employer?.name || '').trim(),
    job_url: job.url || (job.id ? `https://otta.com/jobs/${job.id}` : ''),
    location_text: job.remote ? 'Remote Worldwide' : (job.location || ''),
    salary: job.salary ? `${job.salary.min || ''} - ${job.salary.max || ''}` : '',
    description: (job.description || job.summary || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim(),
    posted_date: job.created_at ? job.created_at.split('T')[0] : new Date().toISOString().split('T')[0],
    tags: Array.isArray(job.tags) ? job.tags.map(t => t.name || t).join(', ') : ''
  }
}));

// Normalize all jobs to standard schema, drop parse-error placeholders
const items = $input.all();
const today = new Date().toISOString().split('T')[0];
const results = [];
for (const item of items) {
  const d = item.json;
  // Skip parse-error placeholders
  if (d._parse_note) continue;
  // Require at minimum a title
  if (!d.job_title && !d.title) continue;
  const job_url = (d.job_url || d.url || '').trim();
  const job_id = job_url || `${(d.company || '').toLowerCase().replace(/\s+/g,'-')}_${(d.job_title || d.title || '').toLowerCase().replace(/\s+/g,'-')}`;
  results.push({
    json: {
      job_id: job_id,
      source: d.source || 'Unknown',
      job_title: (d.job_title || d.title || '').trim(),
      company: (d.company || d.company_name || '').trim(),
      job_url: job_url,
      location_text: (d.location_text || d.location || 'Worldwide').trim(),
      salary: (d.salary || '').trim(),
      description: (d.description || '').slice(0, 8000),
      posted_date: d.posted_date || today,
      tags: (d.tags || '').trim(),
      date_found: today,
      _type: 'job'
    }
  });
}
return results;

// Separate existing jobs (from Sheets) and new scraped jobs
// Then return only new jobs not already in the sheet
const all = $input.all();
const existing = new Set();
const newJobs = [];
// First pass: collect existing URLs
for (const item of all) {
  const d = item.json;
  if (d._type !== 'job') {
    // This came from Google Sheets (no _type field means it's an existing row)
    if (d.job_url) existing.add(d.job_url.trim());
    if (d.job_id) existing.add(d.job_id.trim());
    // Also add company+title combo as backup
    if (d.company && d.job_title) existing.add(`${d.company.toLowerCase()}|${d.job_title.toLowerCase()}`);
  }
}
// Second pass: keep only new jobs
for (const item of all) {
  const d = item.json;
  if (d._type !== 'job') continue;
  const urlKey = d.job_url.trim();
  const idKey = d.job_id.trim();
  const comboKey = `${(d.company || '').toLowerCase()}|${(d.job_title || '').toLowerCase()}`;
  if (existing.has(urlKey) || existing.has(idKey) || existing.has(comboKey)) continue;
  // Not a duplicate - mark as new and add
  existing.add(urlKey);
  existing.add(idKey);
  existing.add(comboKey);
  newJobs.push(item);
}
return newJobs;

// TAIWAN ELIGIBILITY HARD FILTER
// Returns 2 outputs: output 0 = passed, output 1 = rejected
const REJECT_PATTERNS = [
  /\bus[\s-]only\b/i, /\busa[\s-]only\b/i, /\bunited[\s-]states[\s-]only\b/i,
  /\bcanada[\s-]only\b/i, /\bcanadian[\s-]only\b/i,
  /\buk[\s-]only\b/i, /\bunited[\s-]kingdom[\s-]only\b/i,
  /\beu[\s-]only\b/i, /\beurope[\s-]only\b/i, /\beuropean[\s-]union[\s-]only\b/i,
  /\baustralia[\s-]only\b/i, /\baustralian[\s-]only\b/i,
  /must be based in/i, /must live in/i, /must reside in/i,
  /must be authorized to work in/i, /must be eligible to work in/i,
  /must have.*work (authorization|permit|visa)/i,
  /local work permit required/i, /work authorization required/i,
  /\bon-?site\b/i, /office required/i,
  /remote within (us|usa|uk|canada|australia|europe|eu|the us)/i,
  /us residents only/i, /applicants must reside in (us|uk|eu|canada|australia)/i,
  /fixed (us|est|pst|cst|mst|eu|cet|gmt) hours/i,
  /must overlap.*full.*business day.*EST/i,
  /strictly.*9[\s-]to[\s-]5/i,
  /\bhybrid\b/i
];

// Soft keep signals - if any are present, lean toward keeping even if unclear
const KEEP_SIGNALS = [
  /worldwide/i, /work from anywhere/i, /global remote/i, /\bAPAC\b/i,
  /international contractor/i, /contractor (role|agreement|basis)/i,
  /hires? via (Deel|Remote\.com|Oyster|Rippling)/i,
  /\bDeel\b/, /\bRemote\.com\b/, /\bOyster HR\b/,
  /EOR supported/i, /employer of record/i,
  /remote[\s-]first/i, /fully distributed/i, /async[\s-]first/i,
  /distributed team/i
];

const passed = [];
const rejected = [];

for (const item of $input.all()) {
  const d = item.json;
  const text = `${d.job_title} ${d.company} ${d.description} ${d.location_text} ${d.tags}`.toLowerCase();

  let rejectReason = null;
  for (const pattern of REJECT_PATTERNS) {
    if (pattern.test(text)) {
      rejectReason = pattern.toString();
      break;
    }
  }

  if (rejectReason) {
    rejected.push({ json: { ...d, reject_reason: 'Hard filter: ' + rejectReason, reject_stage: 'hard_filter' } });
  } else {
    // Add keep signal strength for downstream scoring
    let keepSignals = 0;
    for (const s of KEEP_SIGNALS) { if (s.test(text)) keepSignals++; }
    passed.push({ json: { ...d, keep_signals: keepSignals } });
  }
}

// Return [passed, rejected] as two outputs
return [passed, rejected];

// AI TAIWAN ELIGIBILITY CHECK
// Calls OpenAI gpt-4o-mini for each job (pass OPENAI_API_KEY as env var)
// Rate limited to ~20 req/s - adds 100ms delay between calls
const jobs = $input.all();
const results = [];
const OPENAI_API_KEY = $env.OPENAI_API_KEY || '';
if (!OPENAI_API_KEY) {
  // No API key: pass all jobs with 'unclear' status
  return jobs.map(item => ({
    json: {
      ...item.json,
      taiwan_eligible: 'unclear',
      ai_reason: 'No OPENAI_API_KEY env variable set - skipping AI check',
      location_risk: 'medium',
      timezone_risk: 'medium',
      contractor_possible: 'unclear',
      ai_decision: 'manual_check'
    }
  }));
}

const PROMPT_TEMPLATE = `You are filtering remote jobs for Jerry, who lives in Taiwan.

The most important rule: Jerry must be able to work this job while physically based in Taiwan.

Do not pass the job only because it says "remote."
Reject the job if it requires the worker to live in the US, Canada, UK, EU, Europe, Australia, or any specific country outside Taiwan.
Reject the job if it requires local work authorization outside Taiwan.
Reject the job if it is hybrid, onsite, or remote within one country only.
Reject the job if it requires fixed working hours that would force Jerry to work through the night in Taiwan (Taiwan = UTC+8).

Keep the job only if one of these is true:
- The job says worldwide remote, work from anywhere, or global remote
- The job says APAC remote
- The job allows international contractors
- The job accepts people based anywhere
- The company hires through EOR, Deel, Remote.com, Oyster, or contractor agreement

Return ONLY valid JSON, no other text:
{
  "taiwan_eligible": "yes/no/unclear",
  "reason": "short reason under 100 chars",
  "location_risk": "low/medium/high",
  "timezone_risk": "low/medium/high",
  "contractor_possible": "yes/no/unclear",
  "decision": "keep/reject/manual_check"
}

Job:
Title: {{TITLE}}
Company: {{COMPANY}}
Location: {{LOCATION}}
Description: {{DESC}}`;

for (let i = 0; i < jobs.length; i++) {
  const d = jobs[i].json;
  const desc = (d.description || '').slice(0, 2500);
  const prompt = PROMPT_TEMPLATE
    .replace('{{TITLE}}', d.job_title)
    .replace('{{COMPANY}}', d.company)
    .replace('{{LOCATION}}', d.location_text)
    .replace('{{DESC}}', desc);

  try {
    const response = await $helpers.httpRequest({
      method: 'POST',
      url: 'https://api.openai.com/v1/chat/completions',
      headers: {
        'Authorization': `Bearer ${OPENAI_API_KEY}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        model: 'gpt-4o-mini',
        messages: [{ role: 'user', content: prompt }],
        max_tokens: 300,
        temperature: 0,
        response_format: { type: 'json_object' }
      })
    });

    const parsed = typeof response === 'string' ? JSON.parse(response) : response;
    const content = parsed?.choices?.[0]?.message?.content || '{}';
    const aiResult = typeof content === 'string' ? JSON.parse(content) : content;

    results.push({
      json: {
        ...d,
        taiwan_eligible: aiResult.taiwan_eligible || 'unclear',
        ai_reason: aiResult.reason || '',
        location_risk: aiResult.location_risk || 'medium',
        timezone_risk: aiResult.timezone_risk || 'medium',
        contractor_possible: aiResult.contractor_possible || 'unclear',
        ai_decision: aiResult.decision || 'manual_check'
      }
    });
  } catch (err) {
    results.push({
      json: {
        ...d,
        taiwan_eligible: 'unclear',
        ai_reason: `AI check error: ${err.message}`,
        location_risk: 'medium',
        timezone_risk: 'medium',
        contractor_possible: 'unclear',
        ai_decision: 'manual_check'
      }
    });
  }

  // Small delay to respect rate limits
  if (i < jobs.length - 1) await new Promise(r => setTimeout(r, 150));
}

// Filter out clear rejects from AI
return results.filter(r => r.json.ai_decision !== 'reject');

// ASYNC CULTURE FILTER
// Checks for async work culture signals in job descriptions
const ASYNC_POSITIVE = [
  { pattern: /\basync(?:hronous)?(?:[\s-]first)?\b/i, score: 'high', label: 'async' },
  { pattern: /asynchronous work/i, score: 'high', label: 'async' },
  { pattern: /flexible hours?/i, score: 'medium', label: 'flexible_hours' },
  { pattern: /flexible schedule/i, score: 'medium', label: 'flexible_hours' },
  { pattern: /work across time zones?/i, score: 'medium', label: 'timezone_flexible' },
  { pattern: /distributed team/i, score: 'medium', label: 'distributed' },
  { pattern: /remote[\s-]first/i, score: 'medium', label: 'remote_first' },
  { pattern: /low meeting culture/i, score: 'high', label: 'async' },
  { pattern: /results[\s-]?oriented/i, score: 'medium', label: 'async' },
  { pattern: /your own hours/i, score: 'high', label: 'flexible_hours' },
  { pattern: /set your own schedule/i, score: 'high', label: 'flexible_hours' },
  { pattern: /no fixed hours/i, score: 'high', label: 'async' },
  { pattern: /overlap.*\d+.*hours?/i, score: 'medium', label: 'partial_overlap' }
];

const ASYNC_NEGATIVE = [
  /strict(?:ly)?.*9[\s-]to[\s-]5/i,
  /fixed (us|est|pst|cst|cet) hours/i,
  /must (work|be online).*EST/i,
  /must (work|be online).*PST/i,
  /must (work|be online).*CET/i,
  /daily live (call|standup|meeting)/i,
  /must overlap full business day/i,
  /required.*9am.*5pm/i,
  /mandatory.*hours/i
];

const results = [];
for (const item of $input.all()) {
  const d = item.json;
  const text = `${d.job_title} ${d.description} ${d.tags}`.toLowerCase();

  // Check negatives first
  let isBlocked = false;
  for (const neg of ASYNC_NEGATIVE) {
    if (neg.test(text)) { isBlocked = true; break; }
  }
  if (isBlocked) continue;

  // Score positives
  let asyncLevel = 'unknown';
  let highHits = 0;
  let medHits = 0;
  for (const pos of ASYNC_POSITIVE) {
    if (pos.pattern.test(text)) {
      if (pos.score === 'high') highHits++;
      else medHits++;
    }
  }

  if (highHits >= 1) asyncLevel = 'high';
  else if (medHits >= 2) asyncLevel = 'medium';
  else if (medHits >= 1) asyncLevel = 'low';
  // Include unknown too - let scoring decide

  results.push({ json: { ...d, async_level: asyncLevel } });
}
return results;

// ROLE FIT + SCORING SYSTEM
// Score 0-100, keep >=70, alert >=85

const ROLE_KEYWORDS = [
  // Tier 1 - direct fit (25 pts)
  { patterns: [/data analyst/i, /data scientist/i, /bi analyst/i, /business intelligence/i, /marketing analyst/i, /growth analyst/i, /performance marketing/i, /ai marketing/i, /ai automation/i, /ai workflow/i, /martech/i, /analytics engineer/i, /marketing data/i], tier: 1 },
  // Tier 2 - adjacent fit (15 pts)
  { patterns: [/data engineer/i, /machine learning/i, /product analyst/i, /revenue analyst/i, /digital marketing/i, /paid media/i, /ppc specialist/i, /seo specialist/i, /automation specialist/i, /growth hacker/i, /creative strategist/i, /content analyst/i], tier: 2 }
];

const SEARCH_KEYWORDS = [
  'async remote', 'asynchronous remote', 'worldwide remote', 'global remote',
  'work from anywhere', 'remote data analyst', 'remote data scientist',
  'remote ai marketing', 'remote marketing analyst', 'remote growth analyst',
  'remote bi analyst', 'remote automation specialist', 'remote ai workflow',
  'ai workflow consultant'
];

const results = [];

for (const item of $input.all()) {
  const d = item.json;
  const text = `${d.job_title} ${d.description} ${d.tags}`.toLowerCase();
  const fullText = `${d.job_title} ${d.company} ${d.description} ${d.location_text} ${d.tags}`.toLowerCase();

  let score = 0;
  const scoreBreakdown = {};

  // --- TAIWAN ELIGIBILITY SCORE (40 pts max) ---
  const te = d.taiwan_eligible;
  const lr = d.location_risk;
  const ks = d.keep_signals || 0;

  if (te === 'yes' || /worldwide|work from anywhere|global remote|anywhere/i.test(fullText) || ks >= 2) {
    score += 40; scoreBreakdown.taiwan = 40;
  } else if (/\bAPAC\b/i.test(fullText) || /asia.*remote/i.test(fullText)) {
    score += 30; scoreBreakdown.taiwan = 30;
  } else if (te === 'unclear' && lr !== 'high') {
    score += 20; scoreBreakdown.taiwan = 20;
  } else {
    score += 0; scoreBreakdown.taiwan = 0;
  }

  // --- ASYNC FIT SCORE (25 pts max) ---
  const al = d.async_level;
  if (al === 'high') { score += 25; scoreBreakdown.async = 25; }
  else if (al === 'medium') { score += 20; scoreBreakdown.async = 20; }
  else if (al === 'low') { score += 15; scoreBreakdown.async = 15; }
  else { score += 10; scoreBreakdown.async = 10; } // unknown = assume remote-first minimum

  // --- ROLE FIT SCORE (25 pts max) ---
  let roleTier = 0;
  let roleCategory = 'other';
  for (const group of ROLE_KEYWORDS) {
    for (const p of group.patterns) {
      if (p.test(text)) {
        if (group.tier === 1 && roleTier < 1) { roleTier = 1; roleCategory = p.toString().replace(/\//g,'').replace(/i$/, ''); }
        else if (group.tier === 2 && roleTier < 2) { roleTier = Math.max(roleTier, 2); roleCategory = p.toString().replace(/\//g,'').replace(/i$/, ''); }
        break;
      }
    }
  }
  if (roleTier === 1) { score += 25; scoreBreakdown.role = 25; }
  else if (roleTier === 2) { score += 15; scoreBreakdown.role = 15; }
  else { score += 0; scoreBreakdown.role = 0; }

  // Also check search keywords for role relevance
  for (const kw of SEARCH_KEYWORDS) {
    if (fullText.includes(kw)) {
      if (scoreBreakdown.role === 0) { score += 10; scoreBreakdown.role = 10; }
      break;
    }
  }

  // --- SALARY FIT SCORE (10-25 pts) ---
  const salaryText = (d.salary || '').replace(/,/g, '');
  const nums = salaryText.match(/\d{3,}/g) || [];
  let salaryScore = 0;
  if (nums.length > 0) {
    const maxSalary = Math.max(...nums.map(Number));
    if (maxSalary >= 5000) { salaryScore = 25; }
    else if (maxSalary >= 3000) { salaryScore = 15; }
    else if (maxSalary > 0) { salaryScore = 10; }
    else { salaryScore = 10; } // listed but non-numeric range
  } else if (salaryText.trim()) {
    salaryScore = 10; // salary mentioned but couldn't parse
  }
  score += salaryScore;
  scoreBreakdown.salary = salaryScore;

  // --- WHY GOOD FIT (for digest) ---
  const reasons = [];
  if (scoreBreakdown.taiwan >= 40) reasons.push('Clearly worldwide/global remote');
  else if (scoreBreakdown.taiwan >= 30) reasons.push('APAC-friendly');
  else if (scoreBreakdown.taiwan >= 20) reasons.push('No country restriction found');
  if (al === 'high') reasons.push('Async-first culture');
  else if (al === 'medium') reasons.push('Flexible hours');
  if (roleTier === 1) reasons.push(`Direct role match: ${roleCategory}`);
  else if (roleTier === 2) reasons.push(`Adjacent role: ${roleCategory}`);
  if (salaryScore >= 25) reasons.push('Salary above $5k/mo');
  else if (salaryScore >= 15) reasons.push('Salary above $3k/mo');
  if (d.contractor_possible === 'yes') reasons.push('Contractor-friendly');

  results.push({
    json: {
      ...d,
      score: Math.min(score, 100),
      score_breakdown: JSON.stringify(scoreBreakdown),
      role_category: roleCategory,
      why_good_fit: reasons.join('; '),
      decision: score >= 85 ? 'apply_immediately' : (score >= 70 ? 'manual_check' : 'reject')
    }
  });
}

// Sort by score descending
results.sort((a, b) => b.json.score - a.json.score);
return results;

